function simpleHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) {
    const char = str.charCodeAt(i);
    hash = (hash << 5) - hash + char;
    hash = hash & hash; // Convert to 32bit integer
  }
  return new Uint32Array([hash])[0].toString(16);
}

for (const item of $input.all()) {
  if (item.json.content != undefined) {
    item.json.hash = simpleHash(item.json.content);
  }
}

return $input.all();

// Calculate Final Score
const text = $json.text;
const jsonBlock = text.replace(/^```json\s*/, '').replace(/\s*```$/, '');

const scores = JSON.parse(jsonBlock);

const finalScore = (

  scores.relevance_score * 0.3 +

  scores.novelty_score * 0.25 +

  scores.viral_score * 0.25 +

  scores.value_score * 0.2

);



return {

  ...scores,

  final_score: Math.round(finalScore),

  should_process: finalScore > 65

};

// Prosty RSS URL Validator dla n8n Code node
// Obsługuje specyfikę n8n response handling

const results = [];

for (const item of $input.all()) {
  const url = item.json.value;

  const validation = {
    urlFormatValid: false,
    serverResponds: false,
    isRssFeed: false,
    finalValid: false,
    errorMessage: null,
    responseTime: null,
    contentLength: 0
  };

  console.log(`🔍 Sprawdzam URL: ${url}`);

  // 1. WALIDACJA FORMATU URL
  try {
    const urlRegex = /^https?:\/\/(www\.)?[-a-zA-Z0-9@:%._\+~#=]{1,256}\.[a-zA-Z0-9()]{1,6}\b([-a-zA-Z0-9()@:%_\+.~#?&//=]*)$/;

    if (urlRegex.test(url) && url.length >= 10 && url.length <= 2048) {
      validation.urlFormatValid = true;
      console.log(`✅ Format URL poprawny`);
    } else {
      validation.errorMessage = 'Niepoprawny format URL';
      console.log(`❌ Niepoprawny format URL`);
    }
  } catch (error) {
    validation.errorMessage = `Błąd walidacji formatu: ${error.message}`;
    console.log(`❌ Błąd format: ${error.message}`);
  }

  // 2. SPRAWDZENIE ZAWARTOŚCI (simplified approach)
  if (validation.urlFormatValid) {
    const startTime = Date.now();

    try {
      console.log(`📡 Pobieram zawartość...`);

      // Uproszczony request bez resolveWithFullResponse
      const content = await this.helpers.httpRequest({
        method: 'GET',
        url: url,
        headers: {
          'User-Agent': 'Mozilla/5.0 (compatible; RSS-Bot/1.0)',
          'Accept': 'application/rss+xml, application/xml, text/xml, */*'
        },
        timeout: 15000,
        encoding: 'utf8'
        // Usuwamy resolveWithFullResponse - n8n ma z tym problemy
      });

      validation.responseTime = Date.now() - startTime;

      // Sprawdź czy dostaliśmy jakąkolwiek zawartość
      if (content && typeof content === 'string' && content.length > 0) {
        validation.serverResponds = true;
        validation.contentLength = content.length;
        console.log(`✅ Serwer odpowiada, pobrano ${content.length} znaków w ${validation.responseTime}ms`);

        // 3. SPRAWDŹ CZY TO RSS/ATOM
        const contentLower = content.toLowerCase().trim();
        const first1000 = contentLower.substring(0, 1000);

        console.log(`🔍 Pierwszy fragment zawartości:`, first1000.substring(0, 200));

        // Sprawdź podstawowe wskaźniki RSS/Atom
        const checks = {
          xml: contentLower.includes('<?xml'),
          rss: contentLower.includes('<rss') || contentLower.includes('version="2.0"'),
          atom: contentLower.includes('<feed') || contentLower.includes('xmlns="http://www.w3.org/2005/atom"'),
          channel: contentLower.includes('<channel>') || contentLower.includes('<channel '),
          items: contentLower.includes('<item>') || contentLower.includes('<item ') || contentLower.includes('<entry>'),
          title: contentLower.includes('<title>'),
          description: contentLower.includes('<description>') || contentLower.includes('<summary>')
        };

        console.log(`🔍 RSS checks:`, checks);

        // Policz pozytywne sprawdzenia
        const positiveChecks = Object.values(checks).filter(Boolean).length;

        // RSS: potrzeba XML + (RSS lub channel) + items
        const isValidRss = checks.xml && (checks.rss || checks.channel) && checks.items;

        // Atom: potrzeba XML + atom + items  
        const isValidAtom = checks.xml && checks.atom && checks.items;

        if (isValidRss || isValidAtom || positiveChecks >= 4) {
          validation.isRssFeed = true;
          const feedType = isValidRss ? 'RSS' : isValidAtom ? 'Atom' : 'Unknown';
          console.log(`✅ Wykryto ${feedType} feed (${positiveChecks}/7 checks passed)`);
        } else {
          validation.errorMessage = `Nie wygląda na RSS/Atom feed (${positiveChecks}/7 checks)`;
          console.log(`❌ Nie RSS/Atom: tylko ${positiveChecks}/7 sprawdzeń pozytywnych`);
        }

      } else {
        validation.errorMessage = 'Pusta odpowiedź lub nieprawidłowy typ';
        console.log(`❌ Pusta lub nieprawidłowa odpowiedź: ${typeof content}, length: ${content ? content.length : 'null'}`);
      }

    } catch (error) {
      validation.responseTime = Date.now() - startTime;

      // Kategoryzuj błędy
      if (error.message.includes('404') || error.message.includes('Not Found')) {
        validation.errorMessage = 'Strona nie istnieje (404)';
        console.log(`❌ 404 - strona nie istnieje`);
      } else if (error.message.includes('timeout') || error.message.includes('ETIMEDOUT')) {
        validation.errorMessage = 'Przekroczono limit czasu';
        console.log(`❌ Timeout`);
      } else if (error.message.includes('ENOTFOUND') || error.message.includes('getaddrinfo')) {
        validation.errorMessage = 'Nie można znaleźć serwera';
        console.log(`❌ DNS/Server nie znaleziony`);
      } else {
        validation.errorMessage = `Błąd: ${error.message}`;
        console.log(`❌ Błąd połączenia: ${error.message}`);
      }
    }
  }

  // 4. WYNIK KOŃCOWY
  validation.finalValid = validation.urlFormatValid && validation.serverResponds && validation.isRssFeed;

  console.log(`📊 WYNIK: format=${validation.urlFormatValid}, server=${validation.serverResponds}, rss=${validation.isRssFeed}, valid=${validation.finalValid}`);

  if (validation.errorMessage) {
    console.log(`⚠️ Błąd: ${validation.errorMessage}`);
  }

  // Zwróć wyniki
  results.push({
    json: {
      ...item.json,
      urlFormatValid: validation.urlFormatValid,
      serverResponds: validation.serverResponds,
      isRssFeed: validation.isRssFeed,
      rss_valid: validation.finalValid,
      responseTimeMs: validation.responseTime,
      validationError: validation.errorMessage,
      contentLength: validation.contentLength,
      validatedAt: new Date().toISOString()
    }
  });
}

console.log(`🏁 Sprawdzono ${results.length} URL-i`);
return results;

function handleDecisionChange(decision, articleId) {
  // Map decision to status
  let newStatus;
  console.log('Decyzja: _' + decision.toLowerCase() + '_, id: ' + articleId);
  switch(decision.toLowerCase().trim()) {
    case 'approve':
      newStatus = 'APPROVED';
      break;
    case 'reject':
      newStatus = 'ARCHIVED';
      break;
    case 'needs more':
      newStatus = 'NEEDS_INVESTIGATION';
      break;
    default:
      newStatus = 'PENDING_REVIEW';
  }

  // Return only required fields
  return {
    articleId: articleId,
    articleStatus: newStatus
  };
}

// Process all input items and return only articleId and articleStatus
const results = [];

for (const item of $input.all()) {
  var decision = item.json.query.decision;
  var articleId = item.json.query.articleId;
  console.log('Decyzja: _' + decision.trim() + '_, id: ' + articleId);
  const processedItem = handleDecisionChange(decision, articleId);

  results.push({
    json: {
      articleId: processedItem.articleId,
      articleStatus: processedItem.articleStatus
    }
  });
}

return results;

function processItem(item) {
  const raw = item.json.output;

  // 1. Strip the Markdown fences
  const jsonBlock = raw.replace(/^```json\s*/, '').replace(/\s*```$/, '');

  // 2. Parse JSON
  let data = JSON.parse(jsonBlock);

  // 3. Clean up the source_url field: keep only the actual URL
  data = data.map(item => {
    const match = item.source_url.match(/https?:\/\/[^\s"<]+/);
    return {
      ...item,
      source_url: match ? match[0] : null
    };
  });

  // 4. Return a single item with the array inside `output`
  return {
    json: {
      output: data
    }
  };
}

// Iteracja po wszystkich items i przetwarzanie każdego z nich
return items.map(processItem);

// Ustawienie długości losowej części identyfikatora (bez timestamp)
const randomLength = 8;

// Zbiór znaków do losowania
const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';

// Funkcja generująca unikalny identyfikator na podstawie timestamp
function generateUniqueId() {
  // Pobranie aktualnego timestamp w milisekundach i konwersja na base36
  const timestamp = Date.now().toString(36);

  // Generowanie losowej części identyfikatora
  let randomPart = '';
  for (let i = 0; i < randomLength; i++) {
    randomPart += chars.charAt(Math.floor(Math.random() * chars.length));
  }

  // Połączenie timestamp z losową częścią
  return timestamp + randomPart;
}

// Wywołanie funkcji i przypisanie wyniku do zmiennej wyjściowej
const uniqueId = generateUniqueId();

// Zwrócenie pojedynczego obiektu jako danych wyjściowych węzła
return {
  json: {
    uniqueSessionId: uniqueId
  }
};

/**
 * Ten skrypt jest przeznaczony do użycia w węźle 'Code' w n8n.
 *
 * Cel:
 * Skrypt iteruje przez wszystkie elementy (items) przekazane z poprzedniego węzła.
 * Dla każdego obiektu JSON w tablicy wejściowej, sprawdza, czy wszystkie jego pola
 * zawierają dane (nie są puste). Na koniec dodaje do każdego obiektu nowe pole
 * `valid_data`, które przyjmuje wartość `true` (jeśli wszystkie pola są wypełnione)
 * lub `false` (jeśli co najmniej jedno pole jest puste).
 *
 * Definicja "pustego" pola:
 * - wartość to null
 * - wartość to undefined
 * - jest to pusty ciąg znaków (string), np. ""
 * - jest to pusta tablica (array), np. []
 */

/**
 * Funkcja pomocnicza do walidacji pojedynczego obiektu JSON.
 * @param {object} obj - Obiekt do sprawdzenia.
 * @returns {boolean} - Zwraca `true`, jeśli obiekt jest prawidłowy, w przeciwnym razie `false`.
 */
function isObjectValid(obj) {
  // Iterujemy przez wszystkie klucze w obiekcie
  for (const key in obj) {
    // Upewniamy się, że sprawdzamy tylko własne właściwości obiektu
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];

      // Sprawdzamy, czy wartość jest pusta zgodnie z naszą definicją
      if (
        value === null ||
        value === undefined ||
        (typeof value === 'string' && value.trim() === '') ||
        (Array.isArray(value) && value.length === 0)
      ) {
        // Jeśli znajdziemy chociaż jedno puste pole, cały obiekt jest nieprawidłowy
        return false;
      }
    }
  }
  // Jeśli pętla zakończy się bez znalezienia pustych pól, obiekt jest prawidłowy
  return true;
}

// Główna pętla, która przetwarza dane wejściowe w n8n.
// `items` to globalna zmienna w węźle Code, zawierająca dane z poprzedniego węzła.
for (const item of $input.all()) {
  // Pobieramy właściwy obiekt JSON z elementu
  const dataObject = item.json;

  // Wywołujemy naszą funkcję walidującą
  const isValid = isObjectValid(dataObject);

  // Dodajemy nowe pole 'valid_data' do obiektu JSON
  dataObject.valid_data = isValid;
}

// Zwracamy zmodyfikowaną tablicę `items`.
// n8n przekaże te dane do następnego węzła w workflow.
return $input.all();

