// Helper: extract plain URL from tag
function extractUrl(linkField) {
  if (!linkField) return "#";
  const m = String(linkField).match(/https?:\/\/[^\s"<]+/);
  return m ? m[0] : "#";
}

const html = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Nowe artykuły do review</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 0; padding: 20px; }
