    th { background-color: #f2f2f2; }
    a { color: #007bff; text-decoration: none; }
  </style>
</head>
<body>
  <h2>${TITLE.replace("{{count}}", articles.length)}</h2>
  <table>
    <thead>
      <tr>
        <th>Title</th>
        <th>Author</th>
        <th>Link</th>
        <th>Summary</th>
        <th>Final score</th>
        <th>Category</th>
        <th>Subcategory</th>
        <th>Priority</th>
        <th>Target audience</th>
      </tr>
    </thead>
    <tbody>
      ${rows}
    </tbody>
  </table>
</body>
</html>
`;

// Return as single item for the next node (e.g., Send Email)
return [{ json: { html } }];

