const node1Data = $('Pobierz artykuł').all(); 
const node2Data = $('Pobierz materiały dodatkowe dla artykułu').all();

// Wyciągnij dane JSON z węzłów
const articles = node1Data.map(item => item.json);
const research = node2Data.map(item => item.json);

// Zagreguj dane
const result = articles.map(article => {
  const relatedResearch = research.filter(item => item.article_id === article.id);

  return {
    id: article.id,
    feed_content_id: article.feed_content_id,
    summary: article.summary,
    author: article.author,
    link: article.link,
    content: article.content,
    relevance_score: article.relevance_score,
    novelty_score: article.novelty_score,
    viral_score: article.viral_score,
    value_score: article.value_score,
    category: article.category,
    subcategory: article.subcategory,
    tags: article.tags,
    priority: article.priority,
    target_audience: article.target_audience,
    key_takeways: article.key_takeways,
    reasoning: article.reasoning,
    status: article.status,
    reviewed_by: article.reviewed_by,
    reviewed_at: article.reviewed_at,
    created_date: article.created_date,
    final_score: article.final_score,
    content_hash: article.content_hash,
    research_content: relatedResearch
  };
});

return result.map(item => ({ json: item }));
